using System;
using UnityEngine;
namespace DazPose.Performer {
 [Serializable] public sealed class CardPresentationState {
  public Vector3 laraPosition,bodyPosition,playerPosition;public Quaternion laraRotation,bodyRotation,viewRotation;
  public Vector3 hipPosition;public bool hidden,bodyHidden,tracking;public string generation,outfit,hair,seat,style,shader,gaze,aura;
  public string pose,overlay,fit,expression,trackTarget,gripTarget;public float intensity,gripPosition,trackingResponse;
  public bool gripActive,gripFollowsMotion;public long driverGeneration;
  internal CardPresentationState(PerformancePresentationSnapshot snapshot){var p=snapshot.Performer;laraPosition=p.Frame.Position;laraRotation=p.Frame.Rotation;bodyPosition=snapshot.Body.Frame.Position;bodyRotation=snapshot.Body.Frame.Rotation;playerPosition=snapshot.View.Root.Position;viewRotation=snapshot.View.Rig.Rotation;hidden=p.Hidden;bodyHidden=snapshot.Body.Hidden;generation=p.Wardrobe?.GenerationId;outfit=p.Wardrobe?.PresetId;hair=p.Wardrobe?.HairKey;seat=p.Seating?.Seat!=null?p.Seating.Seat.name:"none";style=p.Seating?.Style.ToString();shader=p.Material!=null?p.Material.name:"regular";pose=p.DesiredPose!=null?p.DesiredPose.GetEntityId().ToString():"";overlay=p.Seating?.Overlay!=null?p.Seating.Overlay.GetEntityId().ToString():"";fit=p.Fit!=null?p.Fit.GetEntityId().ToString():"";expression=p.Expression!=null?p.Expression.GetEntityId().ToString():"";intensity=p.ExpressionIntensity;tracking=snapshot.View.Tracking;trackTarget=snapshot.View.Target!=null?snapshot.View.Target.GetEntityId().ToString():"";trackingResponse=snapshot.View.TrackingSettings.FollowResponseSeconds;gaze=p.Gaze?.Active==true?(p.Gaze.FollowsTransform?p.Gaze.Target.name:p.Gaze.Point.ToString()):"none";aura=p.Aura!=null?p.Aura.name:"none";gripActive=p.Grip?.Active==true;gripFollowsMotion=p.Grip?.FollowMotion==true;gripPosition=p.Grip?.Position??0;gripTarget=p.Grip?.Target is UnityEngine.Object target?target.GetEntityId().ToString():"";driverGeneration=p.Grip?.Driver!=null?p.Grip.Driver.CommandGeneration:0;var hip=p.Actor.GetComponentsInChildren<Transform>(true);foreach(var t in hip)if(t.name=="hip"){hipPosition=t.position;break;}}
 }
 [Serializable] public sealed class CardPresentationObservation {
  public string phase,card,changedDomains;public long invocation,scope,parentScope;public int writers;public float seconds;
  public CardPresentationState state;public float laraPositionError,laraRotationError,bodyPositionError,cameraRotationError;
  internal CardPresentationObservation(string phase,string card,long invocation,PerformanceOperationScope owner,PerformancePresentationSnapshot snapshot,PerformancePresentationSnapshot entrance,float seconds,string changed=null){this.phase=phase;this.card=card;this.invocation=invocation;scope=owner.Id;parentScope=owner.Parent?.Id??0;writers=owner.WriterCount;this.seconds=seconds;changedDomains=changed;state=new CardPresentationState(snapshot);if(entrance!=null){laraPositionError=Vector3.Distance(snapshot.Performer.Frame.Position,entrance.Performer.Frame.Position);laraRotationError=Quaternion.Angle(snapshot.Performer.Frame.Rotation,entrance.Performer.Frame.Rotation);bodyPositionError=Vector3.Distance(snapshot.Body.Frame.Position,entrance.Body.Frame.Position);cameraRotationError=entrance.View.Tracking?0:Quaternion.Angle(snapshot.View.Rig.Rotation,entrance.View.Rig.Rotation);}}
 }
}
